  const hint=full
    ? "你已经看见：他在抢名册，不是在送名册。药是解药，剑是挡剑，火是想把名单烧给自己。井不是井，是一座被缩小的血月祭坛。他若此刻把名册送下去，今夜失踪的人会在血月那天自己走向柱子。"
    : qmFlag("heardShen")
