      "她先倒热汤。汤是给活人喝的。喝完她才问：废祠那一夜，你看见的是救人，还是一场刚好可以被写成乱的火。她不是要审讯。是要把你写成暗账里的哪一行。一行写“过路客”，一行写“可托之人”。可托之人才能看见下一页——裴衡的旧名、太一的火漆、南疆反写之阵的来路。",
      "云栖若已与你有过一面，会在帘后咳一声。咳声的意思是：情报可以听，人不可以只当情报。苏沐点头。点头时把一缕湿发拨到耳后：我卖消息。消息卖完，若还把你也卖掉，这间坊市就只剩门板。门板不能煮汤。",
      "她把暗账翻到夹层。夹层里有赵衡曾经来买清心散的记名，有陈阿禾帮药庐打杂时换过的一包止血草，有周伯十九年前用旧银换丹的朱印。朱印旁边她用细笔写：这些人若自己走，先问药，再问罪。问罪的人最容易把活人写成税。",
