      "帐外雨更大。更大的雨把三件事拍在门上：应剑，战力会够，人会少一点温度；应道或燃己，门会开得更彻底，枕边会更空；先问人，好感会深，天门那一战会有人替你把伞偏过一寸。一寸的伞，有时比仙法更能让你活着把问题问完。",
      "帘还垂着。垂着的意思是：你还有一页可以把话说完。说完再掀。掀开以后才是选择。选择会走进应剑、改门或燃己。无论哪一种，帐里的人都会在后文出现。出现时可能带剑，可能带问，可能只带一场不肯停的雨。",
