      "一个把微凉的手放进你掌心，凉得像雪，握紧时却不肯松开；一个把尾巴缠上你的腰，毛茸茸的热从腰眼一路爬上来。炭火被她们一冷一热逼得乱跳。天门在头顶压着，人间这一隅却忽然像后宫开了两扇窗。窗里有雪，有狐，有人把脸埋进你肩窝不让你看她红。",
