      "天门已裂。九州的雨重新落下来。落在废祠、南疆、帝京和所有曾经被写成税册的地方。雨洗过门神被刮去的脸，洗过瘴林里的骨头，洗过松开的铁链。洗完以后，两处门同时为你开。一处通向王座，一处通向棋亭。两处都还热着。",
      "王座上若有人，往往是把江山和人一起扛过的那种热。萧景行的凤冠可能还在很远的案上。案上有私旨。私旨被雨打湿，湿的字仍可读：若他还能把人当人，江山也可以让一让。让一让不是亡国。是请你决定：要不要把共主写成下一本税册。",
      "棋亭里若有人，往往是把暗账、银面、假面和残诗一起收过的那种热。苏沐会把最后一盏汤温着。云栖会把你这一行留在账皮外。花千影会把假面推到够不着的地方。她们不谈王位。她们谈：你还肯不肯坐下来，把这一路真正发生了什么说完。说完再走。走去哪里都行。",
      "阿霜会把干外套挂在两处门中间的钩上。挂在中间的意思是：你无论进哪一扇，雨都还在。顾清玄会把剑放在门槛上，刃朝外。刃朝外是护。护的人不管你称不称王。苏晚晴的银面可能戴着，也可能不戴。不戴的脸在终章的雨里，比任何盟印都清楚。",
      "真正的机缘在终章显得很静。静的意思是：没有人逼你立刻进门。赵衡、陈阿禾、周伯的名字还在袖口的灰里。灰搓不掉。搓不掉才对。对的终章要你先把这一路看完，再决定王座、棋亭，或两处都走进去一会儿。一会儿也很长。长到够红颜归卷。",
