        "归墟的潮声还在她呼吸里。潮一涨，她就会轻轻颤。颤不是怕你。是怕古碑又把“青冥子”三个字剜走。她说：青焰护心的人，吻我也该护着点。护着点的意思是：别把我吻成可以随便摘的银面。银面可以扔。人不能扔。",
        "她的手指冰，掌心却热。冰的是海上的风，热的是她自己不肯交税的那一点。她把盟印从你袖里摸出来，又塞回去：印还在，人就还在。在的人今夜不必报姓名。姓名被剜过一次，再报会疼。疼的吻她倒肯给。给的时候眼睛睁着，睁着是怕你把她认成别人。",
