        "她的耳坠是情报站的信物。今夜她摘下来，放进你掌心。放的时候指尖凉。凉的人最会把“我知道很多”说成“我只想让你知道我”。知道她，比知道上方更危险。危险的吻她先给。给完才准你问下一页。",
        "衣上有夜市的香，也有雨。她把你拉进帐最里面，里面才没有耳目。没有耳目的地方，她才肯把腰上的软剑解下。解下软剑等于把命交给你看一眼。看一眼她就红了耳根：看完记得把人还回来。情报可以抄。人抄不走。",
        "她吻得很会计算，计算到后来不算了。不算的云栖会把额头抵着你，声音发哑：你若只想要情报，今晚也可以。也可以的意思是她会痛。痛的账她能做平。做不平的是体温。体温一热，暗账上所有的火漆都像假的。",
        "后半夜她把账收起来，只留你这一行在外面。外面的一行被她用唇印了一下。印不是章。是她把“私账”改成“私”。私的长生很短。短的她也要。要完她才睡，睡时手指还勾着你的袖口，像勾一条不会被上方抽走的线。"
